<?php

namespace Tests\Feature\Payment;

use App\Models\Order;
use App\Models\PaymentAttempt;
use App\Models\PaymentSession;
use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Str;
use Tests\TestCase;

/**
 * The payment QR is generated by us rather than a third-party image service.
 *
 * The checkout previously built the QR URL against api.qrserver.com, which meant
 * every customer's deposit address was sent off-site to be rendered — and a
 * compromise of that service could have swapped the address the customer scanned
 * for an attacker's. These tests pin the replacement's two guarantees: it renders
 * locally, and it can only ever encode a payload we stored ourselves.
 */
class CryptoQrEndpointTest extends TestCase
{
    use RefreshDatabase;

    private function cryptoSession(array $payload): PaymentSession
    {
        $user = User::factory()->create();
        $order = Order::create([
            'user_id' => $user->id,
            'order_number' => 'ORD-'.Str::upper(Str::random(8)),
            'payment_method' => 'crypto',
        ]);
        $attempt = PaymentAttempt::create([
            'order_id' => $order->id,
            'user_id' => $user->id,
            'gateway' => 'nowpayments',
            'idempotency_key' => (string) Str::uuid(),
            'currency' => 'USD',
            'amount' => 20,
        ]);

        return PaymentSession::create([
            'payment_attempt_id' => $attempt->id,
            'provider' => 'nowpayments',
            'session_type' => 'crypto',
            'status' => 'awaiting_transfer',
            'client_reference' => 'SESS_'.Str::random(40),
            'amount' => 20,
            'currency' => 'USD',
            'display_currency' => 'USD',
            'exchange_rate_snapshot' => 1.0,
            'payment_payload' => $payload,
            'customer_email' => $user->email,
            'expires_at' => now()->addMinutes(20),
        ]);
    }

    public function test_it_renders_an_svg_qr_for_a_crypto_session(): void
    {
        $session = $this->cryptoSession([
            'qr_payload' => 'tron:TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t?amount=25.5',
            'pay_address' => 'TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t',
        ]);

        $response = $this->get(route('api.payment-sessions.crypto-qr', $session->id));

        $response->assertOk();
        $response->assertHeader('Content-Type', 'image/svg+xml');
        $this->assertStringContainsString('<svg', $response->getContent());
    }

    /** Falls back to the bare address when no scannable URI was stored. */
    public function test_it_falls_back_to_the_pay_address(): void
    {
        $session = $this->cryptoSession(['pay_address' => 'TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t']);

        $this->get(route('api.payment-sessions.crypto-qr', $session->id))
            ->assertOk()
            ->assertHeader('Content-Type', 'image/svg+xml');
    }

    /**
     * The payload is read from the stored session, never the request, so there is
     * no way to make this render an address we did not issue.
     */
    public function test_it_404s_when_the_session_has_no_crypto_payload(): void
    {
        $session = $this->cryptoSession(['status' => 'awaiting_currency_selection']);

        $this->get(route('api.payment-sessions.crypto-qr', $session->id))->assertNotFound();
    }

    public function test_it_404s_for_an_unknown_session(): void
    {
        $this->get(route('api.payment-sessions.crypto-qr', (string) Str::uuid()))->assertNotFound();
    }
}
